class ListNode {
  constructor(val = 0, next = null) {
    this.val = val;     // the value stored in this node
    this.next = next;   // the next node, or null at the end
  }
}

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val      # the value stored in this node
        self.next = next    # the next node, or None at the end

class ListNode {
    int val;          // the value stored in this node
    ListNode next;    // the next node, or null at the end

    ListNode(int val) {
        this.val = val;
    }
}

struct ListNode {
    int val;          // the value stored in this node
    ListNode* next;   // the next node, or nullptr at the end

    ListNode(int x) : val(x), next(nullptr) {}
};

const head = new ListNode(10);
head.next = new ListNode(20);
head.next.next = new ListNode(30);
head.next.next.next = new ListNode(40);   // 10 -> 20 -> 30 -> 40 -> null

ListNode head = new ListNode(10);
head.next = new ListNode(20);
head.next.next = new ListNode(30);
head.next.next.next = new ListNode(40);   // 10 -> 20 -> 30 -> 40 -> null

ListNode* head = new ListNode(10);
head->next = new ListNode(20);
head->next->next = new ListNode(30);
head->next->next->next = new ListNode(40);   // 10 -> 20 -> 30 -> 40 -> nullptr

function printList(head) {
  let curr = head;
  while (curr !== null) {
    console.log(curr.val);
    curr = curr.next;   // follow the arrow
  }
}

def print_list(head):
    curr = head
    while curr is not None:
        print(curr.val)
        curr = curr.next   # follow the arrow

void printList(ListNode head) {
    ListNode curr = head;
    while (curr != null) {
        System.out.println(curr.val);
        curr = curr.next;   // follow the arrow
    }
}

void printList(ListNode* head) {
    ListNode* curr = head;
    while (curr != nullptr) {
        cout << curr->val << "\n";
        curr = curr->next;   // follow the arrow
    }
}
